export function parseSessionString(str) {
  try {
    const s = new StringSession(String(str).trim());
    const key = s._key;
    if (!key || !key.length) return null;
    return { dcId: s.dcId || 2, authKey: Buffer.from(key) };
  } catch {
    return null;
  }
}

